```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Record the input in the shared store (approved state-rw grant).
        state_rw::put("last-input", &feed_url);

        let seconds = wall_clock::now().seconds;

        let body = http_client::get(&feed_url);
        let fetched = body.chars().count() as u32;

        let notified = notifier::notify("heartbeat");
        // The contract requires notified == true; if the notification was not
        // accepted, trap rather than emit an output that violates it.
        if !notified {
            panic!("notification was not accepted");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

